#!/usr/bin/env bash
# Fetch pinned dependency sources from GitHub as tarballs (no git clone, no submodules).
# Bump a dependency by editing its ref below and re-running.
set -euo pipefail

cd "$(dirname "$0")"

# name  repo  ref (release tag, or commit SHA when the repo has no releases)
DEPS=(
  "lua            lua/lua                     v5.5.1"
  "volk           zeux/volk                   vulkan-sdk-1.4.363.0"
  "Vulkan-Headers KhronosGroup/Vulkan-Headers vulkan-sdk-1.4.363.0"
  "glslang        KhronosGroup/glslang        vulkan-sdk-1.4.363.0"
  "tinygltf       syoyo/tinygltf              v3.0.1"
  "tracy          wolfpld/tracy               v0.14.1"
  "vma            GPUOpen-LibrariesAndSDKs/VulkanMemoryAllocator v3.5.0"
  "stb            nothings/stb                003501f6d7a8668ce8b6d875e34dd97ad0d5d5b5"
  "imgui          ocornut/imgui               v1.93.0"
)

# Resolve a ref to its commit SHA (annotated tags dereferenced via ^{}).
resolve_sha() {
  local repo=$1 ref=$2 out
  if [[ $ref =~ ^[0-9a-f]{40}$ ]]; then
    echo "$ref"
    return
  fi
  out=$(git ls-remote "https://github.com/$repo.git" "refs/tags/$ref" "refs/tags/$ref^{}")
  # Prefer the dereferenced commit line when present.
  { grep '\^{}$' <<<"$out" || echo "$out"; } | head -n1 | cut -f1
}

{
  echo "# Dependency versions"
  echo
  echo "Generated by \`deps/fetch.sh\`. Do not edit by hand."
  echo
  echo "| Name | Repo | Ref | Commit |"
  echo "|---|---|---|---|"
} > VERSIONS.md.tmp

for entry in "${DEPS[@]}"; do
  read -r name repo ref <<<"$entry"
  sha=$(resolve_sha "$repo" "$ref")
  [[ -n $sha ]] || { echo "error: cannot resolve $repo@$ref" >&2; exit 1; }
  echo "fetching $name ($repo@$ref, $sha)"
  rm -rf "$name"
  mkdir -p "$name"
  curl -fsSL "https://codeload.github.com/$repo/tar.gz/$sha" | tar -xz --strip-components=1 -C "$name"
  echo "| $name | https://github.com/$repo | \`$ref\` | \`$sha\` |" >> VERSIONS.md.tmp
done

# Prebuilt Android validation layer (release asset, arm64-v8a only).
VVL_REPO=KhronosGroup/Vulkan-ValidationLayers
VVL_REF=vulkan-sdk-1.4.363.0
VVL_ASSET=android-binaries-1.4.363.0
sha=$(resolve_sha "$VVL_REPO" "$VVL_REF")
[[ -n $sha ]] || { echo "error: cannot resolve $VVL_REPO@$VVL_REF" >&2; exit 1; }
echo "fetching vvl-android ($VVL_REPO@$VVL_REF, $sha)"
rm -rf vvl-android
mkdir -p vvl-android/arm64-v8a
curl -fsSL "https://github.com/$VVL_REPO/releases/download/$VVL_REF/$VVL_ASSET.tar.gz" \
  | tar -xz --strip-components=2 -C vvl-android/arm64-v8a "$VVL_ASSET/arm64-v8a/libVkLayer_khronos_validation.so"
echo "| vvl-android | https://github.com/$VVL_REPO | \`$VVL_REF\` ($VVL_ASSET, arm64-v8a) | \`$sha\` |" >> VERSIONS.md.tmp

mv VERSIONS.md.tmp VERSIONS.md
echo "done"
